    def delete(self, ai_connection_id: str) -> AIConnectionRef:
        """Delete AI Connection

        Permanently deletes an AI connection. Anything scheduled against it,
        such as a dataset run or a risk assessment, stops running.

        Args:
            ai_connection_id: The id of the AI connection.
        """
        return self._api.request(
            HttpMethods.DELETE,
            Endpoints.AI_CONNECTION_ENDPOINT,
            response_schema=AIConnectionRef,
            path={"aiConnectionId": ai_connection_id},
        )

